INSERT INTO translations (lang, key, value) VALUES
  ('en', 'booking.weekly_rent', 'Weekly rent'),
  ('en', 'booking.bond', 'Bond'),
  ('en', 'booking.space_not_found', 'Space not found.'),
  ('en', 'booking.browse_spaces', 'Browse spaces'),
  ('en', 'house_rules.hero_tagline', 'Living together, harmoniously'),
  ('en', 'house_rules.hero_title', 'House Rules'),
  ('en', 'house_rules.breadcrumb_home', 'Home'),
  ('en', 'house_rules.breadcrumb', 'House Rules'),
  ('en', 'house_rules.intro', 'To ensure a comfortable, safe, and respectful living environment for all residents, please read and follow our house rules carefully. These apply to all guests, residents, and visitors.'),
  ('en', 'house_rules.rule_label', 'Rule'),
  ('en', 'house_rules.r1_title', 'Respect & Quiet Hours'),
  ('en', 'house_rules.r1_body', 'All residents are expected to treat each other, staff, and the property with respect. Quiet hours are from 10:00 PM to 8:00 AM on weekdays and 11:00 PM to 9:00 AM on weekends. Loud music, disruptive behaviour, or noise that disturbs other residents is not permitted.'),
  ('en', 'house_rules.r2_title', 'Guests & Visitors'),
  ('en', 'house_rules.r2_body', 'Guests are welcome between 9:00 AM and 10:00 PM. Overnight guests are permitted for a maximum of 2 consecutive nights with prior notification to management. Guests are the responsibility of the resident and must follow all house rules at all times.'),
  ('en', 'house_rules.r3_title', 'Cleanliness & Common Areas'),
  ('en', 'house_rules.r3_body', 'Residents are responsible for keeping their room clean and tidy. Common areas — including the kitchen, bathrooms, laundry, and lounge — must be cleaned after each use. Dishes should be washed immediately and not left in the sink. Weekly inspections may be conducted by management.'),
  ('en', 'house_rules.r4_title', 'No Smoking & No Illegal Substances'),
  ('en', 'house_rules.r4_body', 'MillionStay properties are strictly smoke-free. Smoking is not permitted anywhere inside the building including all rooms, bathrooms, hallways, and stairwells. The use, possession, or distribution of illegal substances on the premises will result in immediate termination of tenancy.'),
  ('en', 'house_rules.r5_title', 'Property Care & Damages'),
  ('en', 'house_rules.r5_body', 'Residents must treat all furniture, appliances, and fixtures with care. Any damages must be reported to management immediately. Costs for repairs due to negligence or misuse will be deducted from the security bond. Please do not attach anything to walls without approval.'),
  ('en', 'house_rules.r6_title', 'Keys & Security'),
  ('en', 'house_rules.r6_body', 'Each resident will be issued with a room key and building access card. Keys must not be duplicated or shared. If a key is lost, a replacement fee applies. Always ensure doors are locked when leaving and do not allow unknown persons to enter the building.'),
  ('en', 'house_rules.r7_title', 'Rent & Payment'),
  ('en', 'house_rules.r7_body', 'Rent is due in advance on the agreed date each week or fortnight. Late payments of more than 7 days may incur a late fee. Persistent late payment may result in a breach notice. Please contact management immediately if you are experiencing financial difficulty.'),
  ('en', 'house_rules.agreement', 'By residing at a MillionStay property you agree to abide by these house rules. Violations may result in a formal warning, bond deduction, or termination of tenancy. If you have questions, please contact us at'),
  ('en', 'house_rules.related_title', 'Related'),
  ('en', 'house_rules.link_faq', 'Frequently Asked Questions'),
