  ('en', 'about.hero_tagline', 'Who we are'),
  ('en', 'about.hero_title', 'About Us'),
  ('en', 'about.breadcrumb_home', 'Home'),
  ('en', 'about.breadcrumb', 'About Us'),
  ('en', 'about.intro_label', 'Introduction'),
  ('en', 'about.intro_title', 'GET TO KNOW US'),
  ('en', 'about.intro_p1', 'MillionStay was founded with a simple mission: to make accommodation in Melbourne genuinely accessible and welcoming for international students and digital nomads. We know that finding a safe, comfortable, and affordable home in a new country is one of the biggest challenges you''ll face — and we''re here to make it easier.'),
  ('en', 'about.intro_p2', 'Our multilingual team (English, Korean, Chinese, Japanese and Thai) works every day to match students with the right rooms, handle paperwork, and ensure every guest feels at home from the moment they arrive.'),
  ('en', 'about.intro_p3', 'We offer flexible stay plans from 1 to 6 months, quality-verified rooms across Melbourne''s best student suburbs, and personal support throughout your entire stay. No hidden fees, no stress — just a great place to call home.'),
  ('en', 'about.team_label', 'Our Team'),
  ('en', 'about.team_ceo', 'Founder & CEO'),
  ('en', 'about.team_ops', 'Operations Manager'),
  ('en', 'about.team_relations', 'Student Relations'),
  ('en', 'about.testimonials_label', 'Testimonials'),
  ('en', 'about.view_more', 'View More'),
  ('en', 'about.t1_text', 'MillionStay made my move to Melbourne so smooth. The team helped me find the perfect room near my university, and the whole process was incredibly easy. I felt supported from day one.'),
  ('en', 'about.t2_text', 'As an international student I was nervous about finding accommodation, but MillionStay was amazing. The staff speak my language and the rooms are exactly as described. Highly recommended!'),
  ('en', 'about.t3_text', 'Great service and beautiful rooms. The flexible monthly plans meant I wasn''t locked into a long lease, which was perfect for my student visa situation. Will definitely use again.'),
  ('en', 'about.blog_label', 'Our Blog'),
  ('en', 'about.blog_sub', 'Tips, guides, and stories to help international students thrive in Melbourne.'),
  ('en', 'about.read_more', 'Read More →'),
  ('en', 'about.b1_tag', 'Guide'),
  ('en', 'about.b1_title', 'Top 5 Suburbs for International Students in Melbourne'),
  ('en', 'about.b1_excerpt', 'Discover the best neighbourhoods close to universities, transport, and dining.'),
  ('en', 'about.b1_date', 'Mar 2025'),
  ('en', 'about.b2_tag', 'Tips'),
  ('en', 'about.b2_title', 'How to Set Up Your Life in Melbourne: A Complete Checklist'),
  ('en', 'about.b2_excerpt', 'From SIM cards to bank accounts — everything you need when you first arrive.'),
  ('en', 'about.b2_date', 'Feb 2025'),
  ('en', 'about.b3_tag', 'Student Life'),
  ('en', 'about.b3_title', 'Melbourne on a Budget: Free & Cheap Things to Do'),
  ('en', 'about.b3_excerpt', 'Explore markets, parks, galleries and events without spending a fortune.'),
  ('en', 'about.b3_date', 'Jan 2025'),
  ('en', 'student.hero_tagline', 'Overseas Student Program'),
  ('en', 'student.hero_title', 'For Students'),
  ('en', 'student.breadcrumb_home', 'Home'),
  ('en', 'student.breadcrumb', 'For Students'),
  ('en', 'student.welcome_label', 'Welcome to Melbourne'),
  ('en', 'student.welcome_title', 'YOUR HOME AWAY FROM HOME'),
  ('en', 'student.intro_p1', 'Arriving in a new country is exciting — but finding a safe, affordable place to live shouldn''t be stressful. MillionStay specialises in helping international students find quality accommodation in Melbourne, with a process designed around your needs.'),
  ('en', 'student.intro_p2', 'We work directly with universities, migration agents and student support services across Melbourne to make your transition as smooth as possible. From the moment you enquire to the day you check out, our multilingual team is by your side.'),
  ('en', 'student.intro_p3', 'Our rooms are located near Melbourne''s leading universities — University of Melbourne, RMIT, Swinburne, Monash, Deakin and more — in well-connected, safe suburban neighbourhoods.'),
  ('en', 'student.browse_rooms', 'Browse Rooms'),
  ('en', 'student.send_enquiry', 'Send Enquiry'),
  ('en', 'student.stat1_label', 'Students Housed'),
  ('en', 'student.stat2_label', 'Melbourne Suburbs'),
  ('en', 'student.stat3_label', 'Languages Spoken'),
  ('en', 'student.stat4_label', 'Support Available'),
  ('en', 'student.benefits_label', 'Why Choose Us'),
  ('en', 'student.benefits_title', 'EVERYTHING A STUDENT NEEDS'),
  ('en', 'student.b1_title', 'Verified & Safe Rooms'),
  ('en', 'student.b1_desc', 'Every room is personally inspected by our team before listing. No scams, no surprises.'),
  ('en', 'student.b2_title', 'Multilingual Support'),
  ('en', 'student.b2_desc', 'Our team speaks English, Korean, Chinese, Japanese and Thai. We''re here to help in your language.'),
  ('en', 'student.b3_title', 'Flexible Stay Plans'),
  ('en', 'student.b3_desc', 'Stay from 4 to 24 weeks. No long-term leases, no stress — just flexibility to match your study schedule.'),
  ('en', 'student.b4_title', 'University-Close Locations'),
  ('en', 'student.b4_desc', 'Rooms in Melbourne''s top student suburbs: Hawthorn, Carlton, South Yarra, St Kilda and more.'),
  ('en', 'student.b5_title', 'Bills Included'),
  ('en', 'student.b5_desc', 'High-speed Wi-Fi, electricity, water and gas included in your weekly rate. No surprise utility bills.'),
  ('en', 'student.b6_title', 'Student-Friendly Process'),
  ('en', 'student.b6_desc', 'Simple online application. Upload documents digitally. No local guarantor required.'),
  ('en', 'student.steps_label', 'Simple Process'),
  ('en', 'student.steps_title', 'HOW IT WORKS'),
  ('en', 'student.s1_title', 'Browse & Apply'),
  ('en', 'student.s1_desc', 'Search rooms by suburb, price and room type. Submit an enquiry form online — takes less than 5 minutes.'),
  ('en', 'student.s2_title', 'We Match You'),
  ('en', 'student.s2_desc', 'Our team reviews your application and matches you with the best available room for your dates and budget.'),
  ('en', 'student.s3_title', 'Move In with Ease'),
  ('en', 'student.s3_desc', 'Pay securely online, sign your agreement digitally, and collect your keys. We''ll guide you every step.'),
  ('en', 'student.reviews_label', 'Student Reviews'),
  ('en', 'student.t1_text', 'MillionStay was a lifesaver. I found a great room in Hawthorn within 24 hours of enquiring. The team even helped me set up my bank account!'),
  ('en', 'student.t2_text', 'As an international student I was nervous about housing, but MillionStay made everything so simple. They responded in Japanese and the room was exactly as described.'),
  ('en', 'student.t3_text', 'Great value for money. Internet is super fast, the room is clean and the location near the tram line makes getting to campus easy.'),
  ('en', 'student.rooms_label', 'Available Now'),
  ('en', 'student.rooms_title', 'BROWSE OUR ROOMS'),
  ('en', 'student.view_all', 'View All Rooms'),
  ('en', 'student.faq_label', 'Got Questions?'),
  ('en', 'student.faq_title', 'FAQ'),
  ('en', 'student.f1_q', 'Do I need a local guarantor?'),
  ('en', 'student.f1_a', 'No. We don''t require a local guarantor. A copy of your student visa and passport is sufficient for most rooms.'),
  ('en', 'student.f2_q', 'Can I pay by international bank transfer?'),
  ('en', 'student.f2_a', 'Yes. We accept international bank transfers, credit/debit cards and some digital wallets.'),
  ('en', 'student.f3_q', 'What is included in the weekly price?'),
  ('en', 'student.f3_a', 'Most rooms include Wi-Fi, electricity, water and gas. Please check individual listings for exact inclusions.'),
  ('en', 'student.f4_q', 'Can I extend my stay?'),
  ('en', 'student.f4_a', 'Absolutely. You can extend your booking subject to room availability. Just contact us at least 2 weeks before your checkout.'),
  ('en', 'student.enquiry_label', 'Get in Touch'),
  ('en', 'student.enquiry_title', 'STUDENT ENQUIRY'),
  ('en', 'student.enquiry_sub', 'Fill in your details and our student support team will contact you within 24 hours.'),
