  ('en', 'agent.hero_tagline', 'Partner Program'),
  ('en', 'agent.hero_title', 'For Agent'),
  ('en', 'agent.breadcrumb_home', 'Home'),
  ('en', 'agent.breadcrumb', 'For Agent'),
  ('en', 'agent.intro_label', 'Grow Together'),
  ('en', 'agent.intro_title', 'PARTNER WITH MILLIONSTAY'),
  ('en', 'agent.intro_p1', 'Are you a migration agent, education consultant or student recruitment agency? MillionStay invites you to join our growing partner network and earn commissions by connecting your clients with premium Melbourne accommodation.'),
  ('en', 'agent.intro_p2', 'We understand the challenges international students face when relocating to Melbourne. Our verified properties, multilingual team and seamless booking process make us the most trusted referral partner for student housing in the city.'),
  ('en', 'agent.intro_p3', 'Whether you work with students from Korea, China, Japan, Thailand, India or beyond — MillionStay has the right accommodation and the right support for every client profile.'),
  ('en', 'agent.apply_partner', 'Apply to Partner'),
  ('en', 'agent.contact_us', 'Contact Us'),
  ('en', 'agent.stat1_label', 'Partner Agencies'),
  ('en', 'agent.stat2_label', 'Commissions Paid'),
  ('en', 'agent.stat3_label', 'Students Placed'),
  ('en', 'agent.stat4_label', 'Partner Satisfaction'),
  ('en', 'agent.benefits_label', 'Why Partner with Us'),
  ('en', 'agent.benefits_title', 'AGENT PARTNER BENEFITS'),
  ('en', 'agent.b1_title', 'Competitive Commission'),
  ('en', 'agent.b1_desc', 'Earn industry-leading referral commissions for every successful booking. Paid promptly upon guest check-in.'),
  ('en', 'agent.b2_title', 'Multilingual Clients'),
  ('en', 'agent.b2_desc', 'Access a wide international student market spanning Korea, China, Japan, Thailand and beyond.'),
  ('en', 'agent.b3_title', 'Real-time Dashboard'),
  ('en', 'agent.b3_desc', 'Track your referrals, commissions and booking statuses through our dedicated agent portal.'),
  ('en', 'agent.b4_title', 'Quality Inventory'),
  ('en', 'agent.b4_desc', 'Our verified properties meet strict quality standards — your clients will be satisfied and trust your recommendations.'),
  ('en', 'agent.b5_title', 'Co-Branding Support'),
  ('en', 'agent.b5_desc', 'Marketing materials, property brochures and social content created with your agency branding included.'),
  ('en', 'agent.b6_title', 'Dedicated Account Manager'),
  ('en', 'agent.b6_desc', 'Every partner agency is assigned a personal account manager for priority support and seamless operations.'),
  ('en', 'agent.how_label', 'Partnership Process'),
  ('en', 'agent.how_title', 'HOW TO JOIN'),
  ('en', 'agent.h1_title', 'Apply to Partner'),
  ('en', 'agent.h1_desc', 'Complete our agent registration form. We''ll review your application and respond within 2 business days.'),
  ('en', 'agent.h2_title', 'Get Approved & Onboarded'),
  ('en', 'agent.h2_desc', 'Once approved, you''ll receive access to our agent portal, property inventory and co-branded materials.'),
  ('en', 'agent.h3_title', 'Refer & Earn'),
  ('en', 'agent.h3_desc', 'Refer clients to MillionStay and track every booking. Commissions are paid promptly upon successful check-in.'),
  ('en', 'agent.feedback_label', 'Partner Feedback'),
  ('en', 'agent.t1_text', 'We''ve been partnering with MillionStay for 2 years. Our Korean student clients love the service and our commission payments are always on time. A true partnership.'),
  ('en', 'agent.t2_text', 'What sets MillionStay apart is their multilingual support. Our Indian students transitioning through Melbourne have found excellent accommodation with zero stress.'),
  ('en', 'agent.t3_text', 'Reliable, professional and genuinely caring about students. The agent dashboard makes tracking referrals so easy. Highly recommended to any migration agent.'),
  ('en', 'agent.reg_label', 'Join Our Network'),
