  ('th', 'house_rules.hero_tagline', 'อยู่ร่วมกันอย่างมีความสุข'),
  ('th', 'house_rules.hero_title', 'กฎระเบียบบ้านพัก'),
  ('th', 'house_rules.breadcrumb_home', 'หน้าหลัก'),
  ('th', 'house_rules.breadcrumb', 'กฎระเบียบบ้านพัก'),
  ('th', 'house_rules.intro', 'เพื่อสร้างสภาพแวดล้อมการอยู่อาศัยที่สะดวกสบาย ปลอดภัย และเคารพซึ่งกันและกัน โปรดอ่านและปฏิบัติตามกฎระเบียบเหล่านี้อย่างเคร่งครัด กฎเหล่านี้ใช้กับผู้เข้าพัก ผู้พักอาศัย และผู้มาเยือนทุกคน'),
  ('th', 'house_rules.rule_label', 'กฎ'),
  ('th', 'house_rules.r1_title', 'การเคารพและเวลาสงบ'),
  ('th', 'house_rules.r1_body', 'ผู้พักอาศัยทุกคนต้องแสดงความเคารพต่อกัน ต่อเจ้าหน้าที่ และต่อทรัพย์สิน เวลาสงบคือ 22:00–08:00 น. ในวันธรรมดา และ 23:00–09:00 น. ในวันหยุดสุดสัปดาห์ ห้ามเปิดเพลงดัง มีพฤติกรรมรบกวน หรือส่งเสียงรบกวนผู้อื่น'),
  ('th', 'house_rules.r2_title', 'แขกและผู้มาเยือน'),
  ('th', 'house_rules.r2_body', 'ยินดีต้อนรับผู้มาเยือนระหว่าง 09:00–22:00 น. อนุญาตให้แขกค้างคืนได้ไม่เกิน 2 คืนติดต่อกัน โดยต้องแจ้งให้ฝ่ายจัดการทราบล่วงหน้า ผู้พักอาศัยต้องรับผิดชอบต่อพฤติกรรมของแขก และแขกต้องปฏิบัติตามกฎทุกข้อ'),
  ('th', 'house_rules.r3_title', 'ความสะอาดและพื้นที่ส่วนกลาง'),
  ('th', 'house_rules.r3_body', 'ผู้พักอาศัยมีหน้าที่รับผิดชอบรักษาห้องของตนให้สะอาดและเป็นระเบียบ พื้นที่ส่วนกลาง ได้แก่ ห้องครัว ห้องน้ำ ห้องซักผ้า และห้องนั่งเล่น ต้องทำความสะอาดทุกครั้งหลังใช้งาน ล้างจานทันทีและห้ามทิ้งไว้ในอ่าง ฝ่ายจัดการอาจตรวจสอบความสะอาดรายสัปดาห์'),
  ('th', 'house_rules.r4_title', 'ห้ามสูบบุหรี่และสารเสพติดผิดกฎหมาย'),
  ('th', 'house_rules.r4_body', 'อาคาร MillionStay เป็นเขตปลอดบุหรี่อย่างเคร่งครัด ห้ามสูบบุหรี่ทุกที่ภายในอาคาร รวมถึงห้องพัก ห้องน้ำ ทางเดิน และบันได การใช้ ครอบครอง หรือแจกจ่ายสารเสพติดผิดกฎหมายจะส่งผลให้ต้องออกจากที่พักทันที'),
  ('th', 'house_rules.r5_title', 'การดูแลทรัพย์สินและค่าเสียหาย'),
  ('th', 'house_rules.r5_body', 'ผู้พักอาศัยต้องดูแลเฟอร์นิเจอร์ เครื่องใช้ไฟฟ้า และอุปกรณ์ต่างๆ อย่างระมัดระวัง ความเสียหายต้องรายงานให้ฝ่ายจัดการทราบทันที ค่าซ่อมแซมที่เกิดจากความประมาทจะถูกหักออกจากเงินประกัน ห้ามติดสิ่งใดบนผนังโดยไม่ได้รับอนุญาต'),
  ('th', 'house_rules.r6_title', 'กุญแจและความปลอดภัย'),
  ('th', 'house_rules.r6_body', 'ผู้พักอาศัยแต่ละคนจะได้รับกุญแจห้องและบัตรผ่านเข้าอาคาร ห้ามทำสำเนาหรือให้ผู้อื่นยืมกุญแจ หากกุญแจหาย จะมีค่าใช้จ่ายในการทำใหม่ ทุกครั้งที่ออกจากห้องต้องตรวจสอบให้แน่ใจว่าล็อคประตูแล้ว และอย่าให้คนแปลกหน้าเข้ามาในอาคาร'),
  ('th', 'house_rules.r7_title', 'ค่าเช่าและการชำระเงิน'),
  ('th', 'house_rules.r7_body', 'ค่าเช่าต้องชำระล่วงหน้าตามวันที่ตกลงไว้รายสัปดาห์หรือรายสองสัปดาห์ หากชำระล่าช้าเกิน 7 วัน อาจมีค่าปรับ การชำระล่าช้าต่อเนื่องอาจนำไปสู่หนังสือแจ้งการละเมิดสัญญา หากมีปัญหาทางการเงิน กรุณาติดต่อฝ่ายจัดการทันที'),
  ('th', 'house_rules.agreement', 'การพักอาศัยใน MillionStay ถือว่าคุณยินยอมปฏิบัติตามกฎระเบียบเหล่านี้ การละเมิดอาจส่งผลให้ได้รับการเตือนอย่างเป็นทางการ หักเงินประกัน หรือยกเลิกสัญญาเช่า หากมีคำถามกรุณาติดต่อเราที่:'),
